#!/bin/bash
# scripts/mbc on programs (its splitter on made-up C is tools/mbc's own tests, `moon test` there): the made-up C of
# those tests built whole and split, the same output; what keeps an object (its command, its compiler, the headers it
# includes); MBC_STORE shared between programs, two at once; a MoonBit program generated by moon (mbc gen) whole and
# split, the same output and the same global symbols (mbc check).
set -u
D=$(cd "$(dirname "$0")" && pwd)
MBC=$D/mbc
CC=${CC:-$(command -v cc || command -v clang || command -v gcc)}
[ -n "$CC" ] || { echo "mbc_test: no C compiler"; exit 0; }
T=$(mktemp -d)
trap 'rm -rf "$T"' EXIT
n=0
fail() { echo "mbc_test: FAIL: $*" >&2; [ ! -f "$T/last.log" ] || cat "$T/last.log" >&2; exit 1; }
ok() { n=$((n + 1)); echo "ok $n - $*"; }
# (a fixture of tools/mbc/csplit_wbtest.mbt: its #| lines)
block() { awk -v name="$1" '$0 ~ "^let " name " " { on = 1; next } on && /^  #\|/ { sub(/^  #\|/, ""); print; next } on { exit }' "$D/../tools/mbc/csplit_wbtest.mbt"; }
{ block prelude_src; echo; block items_src; } > "$T/p.c"
grep -q 'moonbit_init' "$T/p.c" || fail "no fixture from csplit_wbtest.mbt"
"$MBC" csplit "$T/p.c" "$T/warm" 2>/dev/null >/dev/null  # (built before anything is timed)

# the made-up program whole and split, and the link kept when nothing changed
"$CC" "$T/p.c" -o "$T/whole" || fail "the whole file did not compile"
objs=$("$MBC" compile --cc "$CC" --obj "$T/o" "$T/p.c") || fail "mbc compile"
said() { "$MBC" link --out "$T/split" -- "$CC" $objs "$@" -o "$T/split" 2>&1 >/dev/null; }
said | grep -q 'linked split' || fail "the first link"
said | grep -q 'linked already' || fail "the same link again was made again"
said -lm | grep -q 'linked split' || fail "another command was not linked"
[ "$("$T/whole")" = "$("$T/split")" ] || fail "whole and split differ"
[ "$("$T/split")" = 121 ] || fail "the split program's output: $("$T/split")"
ok "the made-up program whole and split: the same output; the link kept"

# what an object is made of: its command, its compiler, the headers it includes
echo '#define H 1' > "$T/h.h"
printf '#include "h.h"\nint x_value(void) { return H; }\n' > "$T/x.c"
wrapper() { printf '#!/bin/sh\n# %s\nexec %s "$@"\n' "$1" "$CC" > "$T/cc.sh"; chmod +x "$T/cc.sh"; }
compiled() {
  # (two at a time: one ends while another is waited for, its end kept for its job)
  "$MBC" compile -j 2 --cc "$T/cc.sh" "--cflags=$1 -I$T" --extra "$T/x.c" --obj "$T/k" "$T/p.c" 2>&1 >/dev/null \
    | tee "$T/last.log" | sed -n 's/.*: \([0-9]*\) of \([0-9]*\) compiled.*/\1 \2/p' | tail -1
}
wrapper one
set -- $(compiled -O1); total=$2; [ "$1" = "$total" ] || fail "the first compile: $1 of $total"
[ "$(compiled -O1)" = "0 $total" ] || fail "nothing changed, not all kept"
echo '#define H 2' > "$T/h.h"
[ "$(compiled -O1)" = "1 $total" ] || fail "a header changed: x.c alone"
[ "$(compiled -O2)" = "$total $total" ] || fail "the flags changed: all"
[ "$(compiled -O2)" = "0 $total" ] || fail "the same flags again: none"
wrapper two
[ "$(compiled -O2)" = "$total $total" ] || fail "the compiler changed: all"
ok "an object kept by its command, its compiler and its headers"

# MBC_STORE: another program's units taken; a header changed, compiled; two programs at once, each unit once
store() {
  MBC_STORE=$T/$2 "$MBC" compile --cc "$CC" --cflags=-O1 --extra "$T/x.c" --obj "$T/$1" "$T/p.c" 2>&1 >/dev/null \
    | sed -n 's/.*: \([0-9]*\) of \([0-9]*\) compiled.*/\1/p' | tail -1
}
echo '#define H 1' > "$T/h.h"
[ "$(store a store)" = "$total" ] || fail "the store's first program"
[ "$(store b store)" = 0 ] || fail "another program's objects not from the store"
echo '#define H 3' > "$T/h.h"
[ "$(store c store)" = 1 ] || fail "x.c's header changed: x.c alone"
store d store2 > "$T/d.n" & store e store2 > "$T/e.n"; wait
[ $(( $(cat "$T/d.n") + $(cat "$T/e.n") )) = "$total" ] || fail "two at once: $(cat "$T/d.n") + $(cat "$T/e.n") of $total"
ok "MBC_STORE between programs, two at once"

# a MoonBit program generated by moon: whole and split, the same output and the same global symbols
if command -v moon >/dev/null; then
  mkdir -p "$T/m/src/main"
  printf 'name = "t/split"\n\nversion = "0.1.0"\n\nsource = "src"\n' > "$T/m/moon.mod"
  printf 'options(\n  "is-main": true,\n)\n' > "$T/m/src/main/moon.pkg"
  cat > "$T/m/src/main/main.mbt" <<'MBT'
let greeting : String = "hello from a global"

let table : Map[String, Int] = { "one": 1, "two": 2, "three": 3 }

trait Shape {
  area(Self) -> Double
}

struct Square(Double)

impl Shape for Square with area(self) { self.0 * self.0 }

fn total(shapes : Array[&Shape]) -> Double {
  shapes.fold(init=0.0, fn(acc, s) { acc + s.area() })
}

fn main {
  println(greeting)
  let adders = Array::makei(5, fn(i) { fn(x : Int) { x + i } })
  let mut sum = 0
  for f in adders {
    sum = sum + f(10)
  }
  println("sum \{sum}")
  println("two is \{table.get("two")}")
  println("area \{total([Square(2.0), Square(3.0)])}")
}
MBT
  c=$("$MBC" gen --dir "$T/m" src/main 2>"$T/gen.log" | tail -1) || { cat "$T/gen.log"; fail "mbc gen"; }
  case "$c" in *main.c) ;; *) fail "mbc gen printed $c";; esac
  MH=${MOON_HOME:-$(dirname "$(dirname "$(command -v moon)")")}
  flags="-I$MH/include -fwrapv -fno-strict-aliasing -Wno-unused-value -O2 -DMOONBIT_ALLOCATOR=MOONBIT_ALLOCATOR_SYSTEM"
  opt=""
  for f in runtime env utf sync_io backtrace; do opt="$opt --optional=$MH/lib/runtime/$f.c"; done
  objs=$("$MBC" compile --cc "$CC" "--cflags=$flags" --obj "$T/mo" $opt "$c") || fail "mbc compile of moon's C"
  rts=$(printf '%s\n' $objs | grep '/x_')
  "$CC" $objs -lm -o "$T/msplit" || fail "the split link"
  "$CC" $flags "$c" $rts -lm -o "$T/mwhole" || fail "the whole link"
  out=$("$T/mwhole")
  case "$out" in *"sum 60"*) ;; *) fail "the whole program said $out";; esac
  [ "$out" = "$("$T/msplit")" ] || fail "moon's program whole and split differ"
  [ "$("$MBC" check --cc "$CC" "--cflags=$flags" --obj "$T/mk" "$c" 2>/dev/null)" = ok ] || fail "mbc check"
  ok "a MoonBit program whole and split: the same output, the same symbols"
fi
echo "mbc_test: $n passed"
